        r, c = q.popleft()
        for d, (dr, dc) in dirs.items():
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(maze) and 0 <= nc < len(maze[0]) and maze[nr][nc] != '#' and (nr, nc) not in visited:
