                    visited.add((nr, nc))
                    heapq.heappush(q, (dist + 1, nr, nc, path + [dname]))
    return None

def dist_to_all(start_r, start_c):
    from collections import deque
    q = deque([(start_r, start_c, 0)])
    visited = set([(start_r, start_c)])
    dists = {}
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while q:
        r, c, d = q.popleft()
        dists[(r, c)] = d
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(maze) and 0 <= nc < len(maze[0]):
                if maze[nr][nc] != "#" and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc, d + 1))
    return dists

